// 📁 src/pages/IssueListPage.js
import React from 'react';
import '../styles/IssueList.css';

const IssueListPage = () => {
  // Sample data with titles
  const issues = [
    { id: 1, submitter: 'TestUser0', title: 'Login page bug', phone: '(123) 456-7890', priority: 'High', status: 'Approved (8/29/2021)' },
    { id: 2, submitter: 'TestUser1', title: 'Payment gateway issue', phone: '(234) 567-8901', priority: 'Medium', status: 'Approved (8/29/2021)' },
    { id: 3, submitter: 'TestUser2', title: 'CSS alignment problem', phone: '(345) 678-9012', priority: 'Low', status: 'Rejected (8/29/2021)' },
    // Add other entries...
  ];

  return (
    <div className="issue-list-container">
      <h1>Issue Management</h1>
      
      <div className="table-container">
        <table className="issue-table">
          <thead>
            <tr>
              <th>Submitter</th>
              <th>Title</th>
              <th>Phone Number</th>
              <th>Priority</th>
              <th>Approval Status</th>
              <th>Action</th>
            </tr>
          </thead>
          <tbody>
            {issues.map(issue => (
              <tr key={issue.id}>
                <td>{issue.submitter}</td>
                <td className="title-cell">{issue.title}</td>
                <td>{issue.phone}</td>
                <td>
                  <span className={`priority-badge ${issue.priority.toLowerCase()}`}>
                    {issue.priority}
                  </span>
                </td>
                <td>{issue.status}</td>
                <td className="action-cell">
                  {issue.status.includes('Pending') ? (
                    <>
                      <button className="approve-btn">Approve</button>
                      <button className="reject-btn">Reject</button>
                    </>
                  ) : (
                    <button className="edit-btn">Edit</button>
                  )}
                </td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>
    </div>
  );
};

export default IssueListPage;
